$bytes = [System.IO.File]::ReadAllBytes($inPath)
$latin1 = [System.Text.Encoding]::GetEncoding(28591)
$raw = $latin1.GetString($bytes)
if ($raw.Length -gt 0 -and $raw[0] -eq [char]0xFEFF) { $raw = $raw.Substring(1) }
$parts = $raw -split "`n", -1
if ($parts.Count -gt 0 -and $parts[$parts.Count-1] -eq '') { $parts = $parts[0..($parts.Count-2)] }

$log = New-Object System.Collections.Generic.List[string]
$sb = New-Object System.Text.StringBuilder
$unk = 0
$idx = 0
foreach ($part in $parts) {
    $idx++
    $nl = "`n"
    $core = $part
    if ($core.EndsWith("`r")) { $core = $core.Substring(0, $core.Length-1); $nl = "`r`n" }
    $zh = $m[$core]
    if ($null -eq $zh) { $unk++; $log.Add("UNMAPPED $idx : $core"); $zh = $core }
    [void]$sb.Append($core).Append([char]0x09).Append($zh).Append($nl)
}
$enc = New-Object System.Text.UTF8Encoding($false)
[System.IO.File]::WriteAllText($outPath, $sb.ToString(), $enc)
$log.Insert(0, "lines=$idx unmapped=$unk keys=$($m.Count)")
[System.IO.File]::WriteAllLines($logPath, $log, $enc)
"lines=$idx unmapped=$unk"
